def count_coprime_pairs(x0: int, y0: int) -> int:
    count = 0
    quotient = y0 // x0
    for a in range(1, quotient + 1):
        b = quotient // a
        if gcd(a, b) == 1:
            if a == b:
                count += 1
            else:
                count += 2
    return count

def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder or not postorder:
        return ""

    root_val = postorder[-1]
    root_index = inorder.index(root_val)

    left_inorder = inorder[:root_index]
    right_inorder = inorder[root_index + 1:]
    left_postorder = postorder[:root_index]
    right_postorder = postorder[root_index:-1]

    return root_val + preorder_traversal(left_inorder, left_postorder) + preorder_traversal(right_inorder, right_postorder)

from collections import deque

from typing import Union

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    if A == B:
        return 0

    queue = deque([(A, 0)])
    visited = set([A])

    while queue:
        current, steps = queue.popleft()
        if current == B:
            return steps

        for src, tgt in rules:
            if src in current:
                new_str = current.replace(src, tgt)
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))

        if steps >= 10:
            return "NO ANSWER!"

    return "NO ANSWER!"

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    This function takes a potential criminal's name (scenario) and a set of liars (liar_count) and checks if
    the statements made by all participants are consistent with this scenario, disregarding any statements
    about the day of the week.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.

    Test Cases:
    >>> check_scenario("ALICE", {"BOB", "CHARLIE"}, {"ALICE": ["I am guilty."], "BOB": ["ALICE is not guilty."], "CHARLIE": []}, {"MONDAY", "TUESDAY"})
    True
    """
    for participant, statements_list in statements.items():
        if participant == scenario:
            continue
        if participant in liar_count:
            for statement in statements_list:
                if "guilty" in statement.lower():
                    return False
        else:
            for statement in statements_list:
                if "guilty" not in statement.lower():
                    return False
    return True

def calculate_score(system: int, points: str) -> list:
    scores = []
    current_score = 0
    lead = 0

    for point in points:
        if point == 'W':
            current_score += 1
            lead = max(lead, current_score - system + 1)
        else:
            current_score -= 1
            lead = max(lead, system - current_score + 1)

        if lead >= system:
            scores.append(f"{current_score}:{system}")
            current_score = 0
            lead = 0

    if current_score > 0:
        scores.append(f"{current_score}:{system}")

    return scores

def remaining_trees_after_clearing(l: int, areas: List[Tuple[int, int]]) -> int:
    remaining = l
    for start, end in areas:
        remaining -= max(0, end - start + 1)
    return remaining

def calculate_arrangements(n, m, a):
    MOD = 10**6 + 7
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            for k in range(1, a[i - 1] + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD

    return dp[n][m]

def jinjin_savings_plan(budgets: List[int]) -> int:
    total_savings = 0
    for month, budget in enumerate(budgets):
        if budget >= 100:
            savings = min(budget, 300)
            total_savings += savings
            budget -= savings
        else:
            return -month
    total_savings *= 1.20
    return int(total_savings)

def hanoi_double_iterative(n: int) -> int:
    # Base cases
    if n == 1:
        return 2
    elif n == 2:
        return 6
    elif n == 3:
        return 14

    # Recursive relation
    return 2 * hanoi_double_iterative(n - 1) + 4
